import pytest
from hypothesis import given, assume
import hypothesis.strategies as st

from solution import cycpattern_check


# ---- obviously-correct reference model (written from spec only) ----

def naive_contains(haystack: str, needle: str) -> bool:
    # Standard substring definition: empty needle is substring of everything.
    if needle == "":
        return True
    n, m = len(haystack), len(needle)
    if m > n:
        return False
    for i in range(n - m + 1):
        match = True
        for j in range(m):
            if haystack[i + j] != needle[j]:
                match = False
                break
        if match:
            return True
    return False


def all_rotations(b: str):
    if b == "":
        return [""]
    return [b[i:] + b[:i] for i in range(len(b))]


def reference(a: str, b: str) -> bool:
    return any(naive_contains(a, r) for r in all_rotations(b))


# ---- spec examples ----

@pytest.mark.parametrize("a,b,expected", [
    ("abcd", "abd", False),
    ("hello", "ell", True),
    ("whassup", "psus", False),
    ("abab", "baa", True),
    ("efef", "eeff", False),
    ("himenss", "simen", True),
])
def test_spec_examples(a, b, expected):
    assert cycpattern_check(a, b) is expected


# ---- boundaries: empty strings ----
# Empty string is a substring of every string, so any rotation check
# with b == "" must be True.

def test_empty_b_always_true():
    assert cycpattern_check("hello", "") is True

def test_empty_both_true():
    assert cycpattern_check("", "") is True

def test_empty_a_nonempty_b_false():
    assert cycpattern_check("", "a") is False

@given(st.text(min_size=0, max_size=8))
def test_empty_b_property(a):
    assert cycpattern_check(a, "") is True


# ---- properties derived from spec ----

@given(st.text(alphabet="abc", min_size=0, max_size=8),
       st.text(alphabet="abc", min_size=0, max_size=8))
def test_equivalence_to_reference_model(a, b):
    assert cycpattern_check(a, b) == reference(a, b)


@given(st.text(alphabet="abcd", min_size=0, max_size=10))
def test_substring_rotation_zero_implies_true(a):
    # If b itself is a (contiguous) substring of a, answer must be True.
    # Take a random slice of a as b.
    if len(a) == 0:
        b = ""
    else:
        i = 0
        j = len(a) // 2
        # ensure valid slice; use deterministic split
        b = a[i:j] if j > i else ""
        # also try full string
        if b == "":
            b = a
    assert naive_contains(a, b)
    assert cycpattern_check(a, b) is True


@given(st.text(alphabet="abc", min_size=1, max_size=6),
       st.integers(min_value=0, max_value=5),
       st.text(alphabet="abc", min_size=0, max_size=4),
       st.text(alphabet="abc", min_size=0, max_size=4))
def test_rotation_of_embedded_substring_implies_true(core, k, pre, post):
    # Embed a rotation of `core` into a larger text; must be detected.
    assume len(core) > 0
    r = core[k % len(core):] + core[:k % len(core)]
    a = pre + r + post
    assert cycpattern_check(a, core) is True


@given(st.text(alphabet="abc", min_size=0, max_size=6),
       st.text(alphabet="abc", min_size=0, max_size=6))
def test_longer_b_cannot_match(a, b):
    # Any rotation of b has length len(b); if longer than a (and b nonempty)
    # it cannot be a substring.
    assume len(b) > len(a) and len(b) > 0
    assert cycpattern_check(a, b) is False


@given(st.text(alphabet="ab", min_size=0, max_size=8),
       st.text(alphabet="ab", min_size=1, max_size=5),
       st.integers(min_value=0, max_value=10))
def test_rotation_invariance(a, b, k):
    # Rotating b permutes the set of rotations, so the answer is invariant.
    rot = b[k % len(b):] + b[:k % len(b)]
    assert cycpattern_check(a, b) == cycpattern_check(a, rot)


@given(st.text(alphabet="abc", min_size=0, max_size=8),
       st.text(alphabet="abc", min_size=0, max_size=5))
def test_returns_bool(a, b):
    assert cycpattern_check(a, b) is True or cycpattern_check(a, b) is False


def test_single_char_present():
    assert cycpattern_check("x", "x") is True


def test_single_char_absent():
    assert cycpattern_check("x", "y") is False


def test_repeated_pattern_rotation():
    # "baa" is a rotation of "aab"; "abab" contains "aba"? No.
    # Direct check: rotations of "baa" are baa, aab, aba; "abab" contains "aba".
    assert cycpattern_check("abab", "aab") is True
    assert reference("abab", "aab") is True
